/**
 * Card icons.
 *
 * Every skill has its own drawing — one SVG per card, generated by `tools/card-icons.mjs` in the
 * Chog's own palette (cream face, spiked mane, big black eyes, pink blush) with a gag built from
 * what the card actually does. The per-element art stays as the fallback, so a card added without
 * regenerating the set shows the element face instead of a broken image.
 */

/** The icon URL for a card: its own art when we have one, the element's otherwise. */
export const cardArt = (id: string | null | undefined, element: string | null | undefined): string =>
  id ? `/cards/${id}.svg` : `/cards/${element ?? 'prism'}.png`;

/** The icon as an `<img>` tag, with the element art wired up as the load-failure fallback. */
export const cardImg = (
  id: string | null | undefined,
  element: string | null | undefined,
  cls: string,
): string => {
  const fallback = `/cards/${element ?? 'prism'}.png`;
  return `<img class="${cls}" src="${cardArt(id, element)}" alt="" onerror="this.onerror=null;this.src='${fallback}'" />`;
};
